        var x = x % m
        if (x < 0) x += m
        return x
    }

    fun valueOf(x: Long): Int {
        var x = x % m
        if (x < 0) x += m
        return x.toInt()
    }

    fun mul(x: Int, y: Int): Int = valueOf(x.toLong() * y)

    fun plus(x: Int, y: Int): Int = valueOf(x + y)

    override fun toString() = "mod $m"
}
